:root {
  font-family: system-ui, sans-serif;
  color: #172c3c;
  background: #f4f7fa;
}
* { box-sizing: border-box; }
body { margin: 0; }
main { max-width: 760px; margin: 64px auto; padding: 24px; }
h1 { font-size: 2.25rem; overflow-wrap: anywhere; }
label { display: block; font-weight: 600; margin-bottom: 8px; }
.form-controls { display: flex; gap: 12px; }
.create-form + .create-form { margin-top: 24px; }
input[type="text"] { flex: 1; min-width: 0; padding: 12px; border: 1px solid #6e8190; border-radius: 6px; font: inherit; }
select { padding: 10px; border: 1px solid #6e8190; border-radius: 6px; background: white; font: inherit; }
input[type="checkbox"] { width: 22px; height: 22px; accent-color: #245678; cursor: pointer; }
.task-filter, .project-filter { margin-top: 24px; }
.tasks { margin-top: 24px; }
.task-row { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 16px; padding: 20px; margin-bottom: 12px; border: 1px solid #c9d4dd; border-radius: 8px; background: white; }
.task-row span { overflow-wrap: anywhere; min-width: 0; }
.task-row form { flex-shrink: 0; }
.task-row .task-rename { flex-basis: 100%; min-width: 0; }
button { padding: 12px 18px; border: 1px solid #245678; border-radius: 6px; background: #245678; color: white; font: inherit; cursor: pointer; }
button:hover { background: #183f5b; }
button:disabled, input:disabled, select:disabled { opacity: 0.6; cursor: not-allowed; }
:focus-visible { outline: 3px solid #ae5b00; outline-offset: 3px; }
.projects { margin-top: 32px; }
.project-row { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 16px; padding: 20px; margin-bottom: 12px; border: 1px solid #c9d4dd; border-radius: 8px; background: white; }
.project-row span { overflow-wrap: anywhere; min-width: 0; }
.project-row form { flex-shrink: 0; }
[role="alert"] { color: #9c2525; }
.empty { color: #526575; }
@media (max-width: 480px) {
  main { margin: 24px auto; padding: 16px; }
  .form-controls { flex-direction: column; }
  .project-row { align-items: flex-start; flex-direction: column; }
}

